check("canonical, redirect, sitemap and trailing-slash signals agree",()=>{const canonical=readFileSync("lib/seo/canonical.ts","utf8"),metadata=readFileSync("lib/seo/metadata.ts","utf8"),routes=readFileSync("lib/seo/route-policy.ts","utf8"),sitemap=readFileSync("app/sitemap.ts","utf8"),nextConfig=readFileSync("next.config.ts","utf8");assert.match(canonical,/path!=="\/"&&path\.endsWith\("\/"\)/);assert.match(canonical,/path\.includes\("\?"\)/);assert.match(metadata,/alternates:\s*\{ canonical: path \}/);assert.match(metadata,/const socialUrl=absoluteCanonicalUrl\(path\)/);assert.match(metadata,/url: socialUrl/);assert.match(routes,/"\/",/);assert.match(sitemap,/url:absoluteCanonicalUrl\(path\)/);assert.match(nextConfig,/trailingSlash:false/);assert.match(nextConfig,/alternateHostname/);assert.match(nextConfig,/x-forwarded-proto/);assert.match(nextConfig,/value:"http"/);assert.match(nextConfig,/destination:`\$\{SITE_URL\}\/\:path\*`/);});
check("legacy redirects are permanent, relevant and never catch all missing pages",()=>{const {LEGACY_REDIRECTS}=loadStandaloneTypeScript("lib/seo/legacy-redirects.ts"),nextConfig=readFileSync("next.config.ts","utf8");const bySource=new Map(LEGACY_REDIRECTS.map(item=>[item.source,item]));for(const [source,destination] of [["/home","/"],["/index.html","/"],["/index.php","/"],["/about","/#about"],["/work","/#selected-work"],["/contact","/#contact"],["/contact.html","/#contact"],["/external/contact.html","/#contact"],["/old-portfolio/contact.html","/#contact"]]){assert.equal(bySource.get(source)?.destination,destination);assert.equal(bySource.get(source)?.permanent,true);}assert.ok(LEGACY_REDIRECTS.every(item=>!item.source.includes(":path")&&!item.source.includes("*")));assert.equal(bySource.has("/portfolio-details.html"),false);assert.equal(bySource.has("/threeJsAnimation.html"),false);assert.match(nextConfig,/\.\.\.LEGACY_REDIRECTS/);});
check("dynamic sitemap covers public collections without state, redirects or employer case studies",()=>{const sitemap=readFileSync("app/sitemap.ts","utf8"),routes=loadStandaloneTypeScript("lib/seo/route-policy.ts");for(const collection of ["INDEXABLE_STATIC_ROUTES","labTools","webGuides","articles"])assert.match(sitemap,new RegExp(`\\.\\.\\.${collection}\\.map`));for(const prefix of ["/lab/","/guides/","/writing/"])assert.ok(sitemap.includes(prefix));assert.match(sitemap,/lastModified:new Date\(article\.date\)/);assert.equal((sitemap.match(/lastModified:/g)||[]).length,1);assert.doesNotMatch(sitemap,/new Date\(\)/);assert.doesNotMatch(sitemap,/\/api\/|seo-checker|searchParams|analysis-results|projects\.map|\/work\/\$\{/);assert.match(sitemap,/duplicate canonical URLs/);assert.ok(routes.INDEXABLE_STATIC_ROUTES.includes("/lab"));assert.ok(!routes.INDEXABLE_STATIC_ROUTES.includes("/about"));assert.ok(!routes.INDEXABLE_STATIC_ROUTES.includes("/work"));assert.ok(!routes.INDEXABLE_STATIC_ROUTES.includes("/contact"));});
check("indexing policy has no global noindex and excludes non-content routes",()=>{const layout=readFileSync("app/layout.tsx","utf8"),notFound=readFileSync("app/not-found.tsx","utf8"),sitemap=readFileSync("app/sitemap.ts","utf8");const policy=loadStandaloneTypeScript("lib/seo/route-policy.ts");assert.match(layout,/robots:\s*\{\s*index:\s*true,\s*follow:\s*true\s*\}/);assert.match(notFound,/index:\s*false/);assert.ok(policy.INDEXABLE_STATIC_ROUTES.includes("/lab"));assert.ok(policy.NON_INDEXABLE_ROUTE_POLICIES.some(item=>item.pattern==="/api/**"));assert.match(sitemap,/INDEXABLE_STATIC_ROUTES/);assert.doesNotMatch(sitemap,/\/api\/|\/lab\/seo-checker/);});
