check("structured data uses one validated renderer and truthful page-specific types",()=>{const schema=readFileSync("lib/seo/structured-data.ts","utf8"),renderer=readFileSync("components/seo/json-ld.tsx","utf8"),layout=readFileSync("app/layout.tsx","utf8"),home=readFileSync("app/page.tsx","utf8"),tool=readFileSync("components/lab/tool-page-layout.tsx","utf8"),guide=readFileSync("app/guides/[slug]/page.tsx","utf8"),article=readFileSync("app/writing/[slug]/page.tsx","utf8");for(const type of ["Person","WebSite","WebApplication","Article","BreadcrumbList"])assert.ok(schema.includes(`"@type":"${type}"`),type);assert.match(renderer,/serializeJsonLd\(data\)/);assert.match(schema,/JSON\.parse\(serialized\)/);assert.match(schema,/replace\(\/<\/g,"\\\\u003c"\)/);assert.doesNotMatch(layout,/application\/ld\+json|"@type"/);assert.match(home,/personStructuredData\(\),websiteStructuredData\(\)/);assert.match(tool,/webApplicationStructuredData/);assert.match(guide,/articleStructuredData/);assert.match(article,/articleStructuredData/);assert.doesNotMatch(schema,/AggregateRating|Review|ratingValue|reviewCount|price|offers|Organization/);});

