check("meaningful images have accurate dimensions, descriptive alternatives and responsive optimization",()=>{const {projects}=loadStandaloneTypeScript("data/projects.ts"),components=["components/work/project-story.tsx","components/work/project-card.tsx","components/sections/home-page.tsx","components/interactions/hero-stage.tsx"].map(file=>readFileSync(file,"utf8")),imageTags=components.join("\n").match(/<Image\b[\s\S]*?\/>/g)??[],nextConfig=readFileSync("next.config.ts","utf8");assert.ok(imageTags.length>=5);for(const tag of imageTags){assert.match(tag,/\balt=/);assert.match(tag,/\bwidth=/);assert.match(tag,/\bheight=/);assert.match(tag,/\bsizes=/);}for(const project of projects){assert.ok(project.imageAlt.length>=30&&project.imageAlt.length<=150,project.slug);assert.doesNotMatch(project.imageAlt,/website interface|image of|SEO|frontend developer/i);assert.match(project.image,/^\/projects\/[a-z0-9]+(?:-[a-z0-9]+)*\.png$/);const file=`public${project.image}`,png=readFileSync(file);assert.equal(png.readUInt32BE(16),project.imageWidth,`${project.slug} width`);assert.equal(png.readUInt32BE(20),project.imageHeight,`${project.slug} height`);}assert.equal(new Set(projects.map(project=>project.imageAlt)).size,projects.length);assert.match(components[0],/alt=""[\s\S]*project\.imageWidth/);assert.match(components[2],/pujan-chapagain-portrait\.png/);assert.match(components[3],/pujan-chapagain-hero\.png/);for(const stale of ["public/portrait.png","public/hero-original.png","public/projects/rishi.png","public/projects/floralpro.png","public/projects/seva.png"])assert.equal(existsSync(stale),false,stale);assert.match(nextConfig,/images:\{formats:\["image\/avif","image\/webp"\]\}/);});
