check("SVG Base64 conversion is Unicode-safe, bounded and reversible",()=>{const {encodeSvgBase64,decodeSvgBase64,MAX_SVG_BYTES}=loadStandaloneTypeScript("lib/svg-base64.ts"),fixtures={ascii:'<svg xmlns="http://www.w3.org/2000/svg"><path d="M0 0h10v10z"/></svg>',unicode:'<svg xmlns="http://www.w3.org/2000/svg"><text>café — naïve résumé</text></svg>',emoji:'<svg xmlns="http://www.w3.org/2000/svg"><text>Design 🎨 · Launch 🚀</text></svg>',nonLatin:'<svg xmlns="http://www.w3.org/2000/svg"><text>नमस्ते · こんにちは · مرحباً</text></svg>',symbols:'  \n<svg xmlns="http://www.w3.org/2000/svg"><text>&amp; © ™ € £ ✓ ∞ →</text></svg>\n  '};for(const [label,source] of Object.entries(fixtures)){const encoded=encodeSvgBase64(source);assert.equal(decodeSvgBase64(encoded),source,`${label} raw Base64 round trip`);assert.equal(decodeSvgBase64(`data:image/svg+xml;base64,${encoded}`),source,`${label} data URI round trip`);}assert.throws(()=>decodeSvgBase64("not base64!"));assert.throws(()=>decodeSvgBase64(btoa("plain text")));assert.throws(()=>encodeSvgBase64("plain text"));assert.throws(()=>encodeSvgBase64(`<svg>${"x".repeat(MAX_SVG_BYTES)}</svg>`));const implementation=readFileSync("lib/svg-base64.ts","utf8"),page=readFileSync("app/lab/svg-base64-converter/page.tsx","utf8"),tool=readFileSync("components/lab/svg-base64-tool.tsx","utf8"),lab=loadStandaloneTypeScript("data/lab-tools.ts");assert.match(implementation,/new TextEncoder\(\)/);assert.match(implementation,/new TextDecoder\("utf-8",\{fatal:true\}\)/);assert.doesNotMatch(implementation,/btoa\(svg\)/);assert.match(page,/SVG to Base64 Converter — Encode & Decode SVG Online/);assert.match(page,/SvgBase64Tool/);assert.match(tool,/type="file" accept="\.svg,image\/svg\+xml"/);assert.match(tool,/onPaste=\{pasteSvg\}/);assert.match(tool,/onDragOver=\{dragOver\}/);assert.match(tool,/onDrop=\{dropFile\}/);assert.match(tool,/acceptSvg\(await file\.text\(\)\)/);assert.doesNotMatch(tool,/<select|input type="radio"/);assert.match(tool,/navigator\.clipboard\.writeText/);assert.match(tool,/DOWNLOAD \.SVG/);assert.ok(lab.labTools.some(item=>item.slug==="svg-base64-converter"));});
