check("mobile-first production performance gate covers every required route",()=>{const audit=readFileSync("scripts/audit-performance.mjs","utf8"),pkg=JSON.parse(readFileSync("package.json","utf8"));for(const route of ["/","/lab","/lab/web-doctor","/lab/svg-base64-converter","/guides/title-tags"])assert.ok(audit.includes(`"${route}"`),route);assert.match(audit,/gzipSync/);assert.match(audit,/javascript:220\*1024,css:40\*1024,html:250\*1024,ttfb:1_000/);for(const check of ["imagesWithoutDimensions","thirdPartyScripts","viewport","javascript","css","ttfb"])assert.ok(audit.includes(check),check);assert.equal(pkg.scripts["audit:performance"],"node scripts/audit-performance.mjs");assert.equal(pkg.scripts["audit:performance:production"],"npm run build && npm run audit:performance");const converter=readFileSync("components/lab/svg-base64-tool.tsx","utf8");assert.doesNotMatch(converter,/fetch\(|XMLHttpRequest|axios|\/api\//);});
check("contact messages are validated and bounded before delivery",()=>{
  const {validateContactInput,CONTACT_LIMITS}=loadStandaloneTypeScript("lib/contact/validation.ts"),requestId="123e4567-e89b-42d3-a456-426614174000",base={email:"person@example.com",message:"A useful project message.",requestId,completionTimeMs:5000};
  assert.deepEqual(validateContactInput({...base,email:" Visitor@Example.com ",message:"  A useful project message.  ",topic:"website",turnstileToken:" token "}),{email:"Visitor@Example.com",message:"A useful project message.",topic:"website",turnstileToken:"token",requestId,honeypot:false,suspiciouslyFast:false});
  assert.throws(()=>validateContactInput({...base,to:"attacker@example.com",bcc:"attacker@example.com"}));
  assert.equal(validateContactInput({...base,website:"spam.example"}).honeypot,true);
  for(const invalid of [{...base,email:"bad"},{...base,email:"person@example.com\r\nBcc:x@example.com"},{...base,message:"x"},{...base,topic:"Injected subject"},{...base,message:"x".repeat(CONTACT_LIMITS.message+1)},{...base,turnstileToken:"x".repeat(CONTACT_LIMITS.turnstileToken+1)},{...base,requestId:"not-a-uuid"},{...base,completionTimeMs:-1},{...base,completionTimeMs:Infinity}])assert.throws(()=>validateContactInput(invalid));
});
check("contact API is origin checked, rate limited and sends through the official Resend SDK with reply-to",()=>{const route=readFileSync("app/api/contact/route.ts","utf8"),resend=readFileSync("lib/contact/resend.ts","utf8"),limiter=readFileSync("lib/contact/rate-limit.ts","utf8"),env=readFileSync(".env.example","utf8"),pkg=JSON.parse(readFileSync("package.json","utf8"));assert.match(route,/origin!==SITE_URL&&origin!==request\.nextUrl\.origin/);assert.match(route,/application\/json/);assert.match(route,/CONTACT_LIMITS\.body/);assert.match(route,/contact\.honeypot/);assert.match(route,/bestEffortContactRateLimit\(key\)/);assert.match(route,/"retry-after"/);assert.match(route,/logContactFailure\(contact\.requestId,error\)/);assert.match(resend,/import "server-only"/);assert.match(resend,/import \{ Resend \} from "resend"/);assert.match(resend,/new Resend\(required\("RESEND_API_KEY"\)\)/);assert.match(resend,/emailClient\.send\(/);assert.match(resend,/replyTo:email/);assert.match(resend,/idempotencyKey:`portfolio-contact\/\$\{requestId\}`/);assert.match(resend,/escapeHtml\(message\)/);assert.equal(typeof pkg.dependencies.resend,"string");assert.doesNotMatch(route+resend,/console\.|password|database|supabase|firebase|NEXT_PUBLIC_RESEND/i);assert.match(limiter,/MAX_REQUESTS=4/);for(const name of ["RESEND_API_KEY","CONTACT_FROM_EMAIL","CONTACT_TO_EMAIL","CONTACT_FROM_NAME"])assert.match(env,new RegExp(`^${name}=$`,"m"));assert.match(env,/^NEXT_PUBLIC_TURNSTILE_SITE_KEY=$/m);assert.match(env,/^TURNSTILE_SECRET_KEY=$/m);assert.doesNotMatch(env,/NEXT_PUBLIC_RESEND_API_KEY|CONTACT_TO_EMAIL=\S+|TURNSTILE_SECRET_KEY=\S+/);});
