check("every contact response is non-cacheable and provider details stay private",()=>{const route=readFileSync("app/api/contact/route.ts","utf8"),diagnostics=readFileSync("lib/contact/diagnostics.ts","utf8"),docs=readFileSync("docs/contact-production-protection.md","utf8");assert.match(route,/"cache-control":"private, no-store, max-age=0"/);assert.match(route,/"pragma":"no-cache"/);assert.match(route,/"expires":"0"/);assert.match(route,/"vary":"Origin"/);assert.match(route,/headers:\{\.\.\.extra,\.\.\.responseHeaders\}/);assert.doesNotMatch(route,/error\.message|error\.stack|JSON\.stringify\(error\)|provider response/i);assert.doesNotMatch(diagnostics,/error\.message|error\.stack|email|message|api.?key/i);assert.match(docs,/credentials, stack traces and internal error messages are never returned/);});
