check("homepage gives recruiters one deliberate continuous professional sequence",()=>{const home=readFileSync("components/sections/home-page.tsx","utf8"),css=readFileSync("app/globals.css","utf8");for(const source of ["projects","skills","experience","education"])assert.match(home,new RegExp(`\\b${source}\\b`));const order=["01 / Selected work","02 / The Lab","03 / Skills &amp; capability","04 / Experience","05 / Education","06 / About","07 / Contact"].map(label=>home.indexOf(label));assert.ok(order.every(index=>index>=0));assert.deepEqual([...order].sort((a,b)=>a-b),order);for(const destination of ["/lab","/lab/web-doctor","/lab/svg-base64-converter"])assert.ok(home.includes(`href=\"${destination}\"`),destination);for(const [id,index] of [["lab","02"],["skills","03"],["experience","04"],["education","05"],["about","06"],["contact","07"]])assert.match(home,new RegExp(`id=\"${id}\" data-section=\"${index}\"`));for(const section of ["home-expertise","home-experience","home-lab","home-education","home-about","home-contact"])assert.ok(home.includes(section),section);assert.match(home,/frontend developer based in Glasgow/);assert.match(css,/\.home-expertise \{ background:/);assert.match(css,/\.home-lab \{ border-block:/);assert.match(css,/\.home-education li \{ display:grid/);assert.match(css,/\.home-contact \{ display:grid[\s\S]*background:var\(--color-ink\)/);});

check("homepage Lab presents six usable tools with two clear featured products",()=>{const home=readFileSync("components/sections/home-page.tsx","utf8"),data=readFileSync("data/lab-tools.ts","utf8"),education=readFileSync("components/lab/tool-education.tsx","utf8"),doctorEducation=readFileSync("components/lab/web-doctor-education.tsx","utf8"),css=readFileSync("app/globals.css","utf8"),{labTools}=loadStandaloneTypeScript("data/lab-tools.ts");assert.equal(labTools.length,6);assert.deepEqual(labTools.map(tool=>tool.title),["WEB DOCTOR","Meta Tag Generator","Colour Contrast Checker","CSS Clamp Generator","Open Graph Preview","SVG ↔ Base64 Converter"]);assert.match(home,/featuredToolSlugs=new Set\(\["web-doctor","svg-base64-converter"\]\)/);assert.match(home,/featuredLabTools\.map\(tool=><article/);assert.match(home,/otherLabTools\.map\(tool=><article/);assert.match(home,/>Open tool <ArrowUpRight/);assert.match(home,/>Read documentation <ArrowUpRight/);assert.match(home,/`\/lab\/\$\{tool\.slug\}#documentation`/);assert.match(education,/className="tool-education" id="documentation"/);assert.match(doctorEducation,/className="doctor-education" id="documentation"/);assert.doesNotMatch(data,/\b(?:revolutionary|powerful|cutting-edge|comprehensive|ultimate|intelligent|professional-grade)\b/i);assert.ok(labTools.every(tool=>tool.description.length>=50));assert.match(css,/\.home-lab-featured \{ display:grid; grid-template-columns:repeat\(2/);assert.match(css,/\.home-lab-directory article \{ display:grid/);});

