check("homepage capabilities are grouped evidenced and free of fake proficiency ratings",()=>{const skills=readFileSync("data/skills.ts","utf8"),home=readFileSync("components/sections/home-page.tsx","utf8"),css=readFileSync("app/globals.css","utf8");for(const group of ["Frontend engineering","UI and interaction","CMS and interface systems","Workflow and tooling","Microsoft workplace tools"])assert.ok(skills.includes(`\"${group}\"`),group);for(const demonstrated of ["TypeScript","React","Vue","Next.js","Responsive UI","Accessibility","Motion","Design systems","WordPress","GitHub","Figma","Microsoft Excel"])assert.ok(skills.includes(`\"${demonstrated}\"`),demonstrated);assert.doesNotMatch(skills,/Python|FastAPI|REST APIs/);assert.doesNotMatch(skills+home,/\b(?:[1-9]\d?|100)%\s*(?:React|JavaScript|HTML|CSS)|progress-bar|proficiency/i);assert.match(home,/className="capability-list"[\s\S]*String\(groupIndex\+1\)\.padStart\(2,"0"\)[\s\S]*String\(itemIndex\+1\)\.padStart\(2,"0"\)/);assert.match(home,/No percentage scores/);assert.match(css,/\.capability-list article \{ display:grid/);});

