check("visual language avoids generic AI template decoration",()=>{const css=readFileSync("app/globals.css","utf8"),home=readFileSync("components/sections/home-page.tsx","utf8"),hero=css.slice(css.indexOf(".hero-art {"),css.indexOf(".hero-project-canvas"));assert.doesNotMatch(css,/#[a-f\d]{0,2}(?:7c3aed|8b5cf6|a855f7|9333ea)|purple/i);assert.doesNotMatch(home,/\b(?:bento|glass|pill|badge|gradient|glow)\b/i);assert.doesNotMatch(hero,/border-radius:50%|filter:blur|radial-gradient/);assert.match(hero,/\.hero-art i:first-child[\s\S]*width:36vw; height:26vw[\s\S]*rotate\(-3deg\)/);assert.match(hero,/\.hero-art i:nth-child\(2\)[\s\S]*width:12vw; height:26vw[\s\S]*var\(--color-accent\)/);assert.match(css,/\.site-header[^{]*\{[^}]*background:var\(--color-canvas\)/);assert.doesNotMatch(css.match(/\.site-header \{[^}]+\}/)?.[0]??"",/backdrop-filter|transparent/);assert.match(css,/\.finding-filters \{ background:var\(--color-canvas\); backdrop-filter:none; \}/);assert.match(css,/\.search-preview-result,\.contact-chat-trigger,\.contact-chat-dialog \{ box-shadow:none; \}/);assert.match(css,/\.command-dialog::backdrop,\.contact-chat-dialog::backdrop \{ backdrop-filter:none; \}/);});

check("signature PUJAN logo preserves its original vector geometry",()=>{const geometry=loadStandaloneTypeScript("components/navigation/logo-geometry.ts"),component=readFileSync("components/navigation/animated-logo.tsx","utf8"),source=readFileSync("src/img/logo/logosvg.svg","utf8"),css=readFileSync("app/globals.css","utf8"),sourcePaths=[...source.matchAll(/<path[^>]* d="([^"]+)"/g)].map(match=>match[1]);assert.equal(geometry.PUJAN_LOGO_SOURCE_VIEW_BOX,source.match(/viewBox="([^"]+)"/)?.[1]);assert.equal(geometry.PUJAN_LOGO_SOURCE_FILL,"#e45447");assert.equal(sourcePaths.length,6);assert.deepEqual(geometry.pujanLogoSourceOrder,["u","j","a","n","slash","arrow"]);assert.deepEqual(sourcePaths,geometry.pujanLogoSourceOrder.map(name=>geometry.pujanLogoPaths[name]));assert.deepEqual(geometry.pujanLogoDrawOrder,["slash","arrow","u","j","a","n"]);assert.deepEqual([...geometry.pujanLogoDrawOrder].sort(),[...geometry.pujanLogoSourceOrder].sort());assert.deepEqual(geometry.pujanLogoLetterGroups.flatMap(group=>group.paths),geometry.pujanLogoDrawOrder);assert.equal(new Set(Object.values(geometry.pujanLogoPaths)).size,6);assert.match(component,/viewBox=\{PUJAN_LOGO_DISPLAY_VIEW_BOX\}/);assert.match(component,/pujanLogoLetterGroups\.map/);assert.equal((component.match(/paths\.map/g)??[]).length,2);assert.doesNotMatch(component,/<text|const paths/);assert.match(component,/aria-label="Pujan"/);assert.match(css,/--color-brand: #e45447/);assert.match(css,/\.logo-stroke \{ fill:none; stroke:var\(--color-brand\)/);assert.match(css,/\.logo-fill \{ fill:var\(--color-brand\)/);});

check("PUJAN logo writes P U J A N sequentially and resets without blinking",()=>{const component=readFileSync("components/navigation/animated-logo.tsx","utf8"),css=readFileSync("app/globals.css","utf8");assert.match(component,/data-letter=\{letter\}/);assert.match(component,/logo-letter-\$\{letter\}/);for(const letter of ["p","u","j","a","n"]){assert.match(css,new RegExp(`\\.logo-letter-${letter}\\.logo-stroke \\{ animation-name:logo-write-${letter}`));assert.match(css,new RegExp(`\\.logo-letter-${letter}\\.logo-fill \\{ animation-name:logo-fill-${letter}`));assert.match(css,new RegExp(`@keyframes logo-write-${letter}`));assert.match(css,new RegExp(`@keyframes logo-fill-${letter}`));}for(const start of ["0%","13%","26%","39%","52%"]){assert.ok(css.includes(start),start);}assert.match(css,/68%,88% \{ stroke-dashoffset:0; opacity:1; \} 96%,100% \{ stroke-dashoffset:0; opacity:0; \}/);assert.match(css,/70%,88% \{ opacity:1; \} 96%,100% \{ opacity:0; \}/);assert.match(css,/animation-iteration-count:infinite/);assert.match(css,/@media\(prefers-reduced-motion:reduce\)[\s\S]*\.hero-support,\.story-copy,\.logo-fill \{ opacity:1!important; \}[\s\S]*\.logo-stroke,\.logo-glint \{ display:none; \}/);assert.doesNotMatch(css,/logo-(?:write|fill)-[pujan][^}]*steps\(|animation-timing-function:steps/);});

