check("decorative motion preserves semantics focus and WCAG contrast",()=>{const css=readFileSync("app/globals.css","utf8"),hero=readFileSync("components/interactions/hero-stage.tsx","utf8"),story=readFileSync("components/work/project-story.tsx","utf8"),logo=readFileSync("components/navigation/animated-logo.tsx","utf8");const luminance=hex=>{const channels=hex.match(/../g).map(value=>parseInt(value,16)/255).map(value=>value<=.04045?value/12.92:((value+.055)/1.055)**2.4);return .2126*channels[0]+.7152*channels[1]+.0722*channels[2];},contrast=(a,b)=>(Math.max(luminance(a),luminance(b))+.05)/(Math.min(luminance(a),luminance(b))+.05);assert.ok(contrast("b43d33","f0eee8")>=4.5);assert.ok(contrast("5b5a56","f0eee8")>=4.5);assert.ok(contrast("e45447","151515")>=4.5);assert.match(css,/:focus-visible \{ outline:2px solid var\(--color-focus-ring\)/);assert.doesNotMatch(css,/(?:^|\})\s*:focus-visible\s*\{[^}]*outline:\s*(?:0|none)/m);for(const source of [hero,story])assert.match(source,/aria-hidden="true"/);assert.match(logo,/role="img"[\s\S]*aria-label="Pujan"/);assert.doesNotMatch(hero+story+logo,/tabIndex=\{-1\}|onKeyDown[^}]*preventDefault\(\).*Tab/);for(const selector of ["doctor-education-topics a:hover","breadcrumbs a:hover","summary:hover","social-preview-trigger:hover"])assert.ok(css.includes(`.${selector} { color:var(--color-link-hover); }`)||css.includes(`${selector} { color:var(--color-link-hover); }`),selector);assert.match(css,/\.changelog-page \.changelog-version,\.search-preview-result h3 \{ color:var\(--color-link-hover\); \}/);assert.doesNotMatch(css,/@keyframes[^}]+(?:50%|to)[^}]*background:(?:white|#fff)[\s\S]{0,120}(?:black|#000)/i);});

check("light and dark surface tokens meet text link button and control contrast",()=>{const css=readFileSync("app/globals.css","utf8");const luminance=hex=>{const channels=hex.match(/../g).map(value=>parseInt(value,16)/255).map(value=>value<=.04045?value/12.92:((value+.055)/1.055)**2.4);return .2126*channels[0]+.7152*channels[1]+.0722*channels[2];},contrast=(a,b)=>(Math.max(luminance(a),luminance(b))+.05)/(Math.min(luminance(a),luminance(b))+.05);for(const [foreground,background] of [["151515","f0eee8"],["5b5a56","f0eee8"],["5b5a56","d9d6cf"],["b43d33","f0eee8"],["f0eee8","151515"],["e45447","151515"]])assert.ok(contrast(foreground,background)>=4.5,`${foreground} on ${background}`);for(const background of ["f0eee8","d9d6cf","151515"])assert.ok(contrast("77756f",background)>=3,`control border on ${background}`);assert.match(css,/--color-muted: #5b5a56/);assert.match(css,/--color-control-border: #77756f/);assert.match(css,/input:not\(\[type="hidden"\]\),textarea,select \{ border-color:var\(--color-control-border\); \}/);assert.match(css,/\.doctor-url-field input \{ border:0; \}/);assert.match(css,/\.standfirst \{[^}]*color:var\(--color-muted\)/);assert.match(css,/\.button-primary \{ background:var\(--color-ink\); color:var\(--color-canvas\); \}/);assert.match(css,/\.button-primary:is\(:hover,:focus-visible\)[^}]*background:var\(--color-accent\); color:var\(--color-ink\)/);});

