check("primary navigation exposes a semantic scroll-aware active state",()=>{const component=readFileSync("components/navigation/primary-navigation.tsx","utf8"),navigation=readFileSync("components/navigation/site-navigation.tsx","utf8"),css=readFileSync("app/globals.css","utf8");assert.match(component,/"use client"/);assert.match(component,/usePathname\(\)/);assert.match(component,/new IntersectionObserver/);assert.match(component,/document\.getElementById\(link\.sectionId\)/);assert.match(component,/rootMargin:"-18% 0px -62%"/);assert.match(component,/pathname==="\/"\?activeSection===link\.sectionId/);assert.match(component,/pathname\.startsWith\("\/lab"\)/);assert.match(component,/aria-current=\{active\?"location":undefined\}/);assert.match(navigation,/<PrimaryNavigation links=\{primaryLinks\} \/>/);assert.match(css,/\.site-header nav a\[aria-current\] \{ color:var\(--color-link-hover\); transform:translateY\(-1px\); \}/);assert.match(css,/:where\(#selected-work,#lab,#skills,#experience,#education,#about,#contact\) \{ scroll-margin-top:6rem; \}/);});

check("only the confirmed duplicate hero derivative is removed",()=>{const hero=readFileSync("public/pujan-chapagain-hero.png"),portrait=readFileSync("public/pujan-chapagain-portrait.png"),heroSource=readFileSync("src/img/banner1.jpg"),portraitSource=readFileSync("src/img/about-me-2.png");assert.equal(existsSync("src/img/banner1.png"),false);assert.ok(hero.byteLength>0);assert.ok(portrait.byteLength>0);assert.ok(heroSource.byteLength>hero.byteLength);assert.ok(portraitSource.byteLength>0);assert.equal(Buffer.compare(portrait,portraitSource),0);});

check("animation performance avoids continuous layout and large filter work",()=>{const css=readFileSync("app/globals.css","utf8");assert.doesNotMatch(css,/transition(?:-property)?:\s*[^;}]*\b(?:width|height|top|left)\b/i);const keyframes=[...css.matchAll(/@keyframes\s+[\w-]+\s*\{(?:[^{}]|\{[^{}]*\})*\}/g)].map(match=>match[0]).join("\n");assert.doesNotMatch(keyframes,/\b(?:width|height|top|left)\s*:/i);assert.match(css,/\.timeline article::after \{[^}]*transform:scaleX\(0\)[^}]*transition:transform/);assert.match(css,/\.timeline article:hover::after \{ transform:scaleX\(1\)/);assert.match(css,/stroke-dashoffset/);assert.match(css,/@keyframes hero-portrait-settle \{ from \{ transform:scale\(1\.04\); filter:blur\(3px\)/);assert.doesNotMatch(css,/filter:blur\((?:[4-9]|\d{2,})px\)[^}]*animation-iteration-count:infinite|animation:[^;}]*infinite[^}]*filter:blur/i);const infiniteRules=[...css.matchAll(/[^{}]+\{[^{}]*infinite[^{}]*\}/g)].map(match=>match[0]).join("\n");assert.doesNotMatch(infiniteRules,/(?:^|[;{])\s*(?:width|height|top|left|filter)\s*:/);});

check("continuous interactions schedule at most one DOM update per animation frame",()=>{const hero=readFileSync("components/interactions/hero-stage.tsx","utf8"),magnetic=readFileSync("components/interactions/use-magnetic-control.ts","utf8"),navigation=readFileSync("components/navigation/site-navigation.tsx","utf8"),story=readFileSync("components/work/project-story.tsx","utf8");assert.match(hero,/if\(pointerFrame\)return;[\s\S]*pointerFrame = requestAnimationFrame/);assert.match(hero,/if\(scrollFrame\)return;[\s\S]*scrollFrame = requestAnimationFrame/);assert.match(hero,/new ResizeObserver/);assert.doesNotMatch(hero,/stage\.offsetHeight|useState|setState/);assert.match(magnetic,/pendingRef\.current=\{element,clientX:event\.clientX,clientY:event\.clientY\}/);assert.match(magnetic,/if\(frameRef\.current\)return;[\s\S]*requestAnimationFrame/);assert.doesNotMatch(magnetic,/useState/);assert.match(navigation,/const compact=\(\)=>\{if\(frame\)return;frame=requestAnimationFrame/);assert.match(story,/setActiveIndex\(current=>current===index\?current:index\)/);assert.doesNotMatch(story,/addEventListener\(["'](?:scroll|pointermove|mousemove)/);});

check("major interactive families have smooth intentional hover feedback",()=>{const css=readFileSync("app/globals.css","utf8");assert.match(css,/:where\(a\[href\],button,input,textarea,select,summary\) \{[^}]*filter var\(--duration-fast\) var\(--ease-smooth\)/);for(const selector of [".site-header nav a:hover:after",".button-primary:is(:hover,:focus-visible)",".project:is(:hover,:focus-within) .project-media",".capability-list li:hover",".timeline article:hover::after",".lab-list>a:hover",".social-list a:hover svg",".contact-chat-trigger:hover",".copy-snippet button:hover"]){assert.ok(css.includes(selector),selector);}assert.match(css,/\.lab-list>a:hover,\.lab-list>a:focus-visible \{[^}]*background:var\(--color-surface\)/);assert.match(css,/\.lab-list>a:hover svg,\.lab-list>a:focus-visible svg \{[^}]*color:var\(--color-link-hover\); transform:translate\(3px,-3px\)/);assert.doesNotMatch(css,/:hover[^}]*transition:\s*none/);});

check("animation lifecycle survives resize visibility scrolling and reduced motion changes",()=>{const hero=readFileSync("components/interactions/hero-stage.tsx","utf8"),logo=readFileSync("components/navigation/animated-logo.tsx","utf8"),css=readFileSync("app/globals.css","utf8");for(const query of ["simpleMobileMotion","reducedMotion","finePointer"])assert.match(hero,new RegExp(`${query}\\.addEventListener\\(\"change\",syncEffects\\)`));assert.match(hero,/document\.addEventListener\("visibilitychange",syncEffects\)/);assert.match(hero,/const shouldRun=!simpleMobileMotion\.matches&&!reducedMotion\.matches&&document\.visibilityState==="visible"/);assert.match(hero,/const stopEffects=\(\)=>\{[\s\S]*resetPointer\(\);[\s\S]*resetScroll\(\)/);assert.match(hero,/stage\.style\.setProperty\("--hero-scroll", "0"\)/);assert.match(hero,/removeEventListener\("change",syncEffects\)/);assert.match(logo,/document\.visibilityState === "visible"/);assert.match(logo,/document\.addEventListener\("visibilitychange", syncMotion\)/);assert.match(css,/body \{[^}]*overflow-x:clip/);assert.match(css,/@media\(prefers-reduced-motion:reduce\)[\s\S]*animation:none!important/);assert.match(css,/\.motion-reveal-text,\.motion-reveal-image,\.motion-section-intro \{ opacity:1!important; \}/);});

check("hero portrait preserves the centred face across every responsive composition",()=>{const hero=readFileSync("components/interactions/hero-stage.tsx","utf8"),css=readFileSync("app/globals.css","utf8"),png=readFileSync("public/pujan-chapagain-hero.png");assert.equal(png.readUInt32BE(16),1440);assert.equal(png.readUInt32BE(20),500);assert.match(hero,/alt=\{`\$\{PERSON_NAME\} wearing sunglasses`\}/);assert.match(hero,/width=\{1440\}[\s\S]*height=\{500\}/);assert.match(css,/\.hero-original-art \{[^}]*left:50%[^}]*width:min\(72vw,82rem\)[^}]*translate3d\(-50%/);assert.match(css,/\.hero-portrait-frame \{[^}]*clip-path:inset\(var\(--hero-clip-top\) 2% var\(--hero-clip-bottom\) 2%\)/);assert.match(css,/\.hero-original-art img \{[^}]*height:auto; object-fit:contain; object-position:50% 50%/);assert.match(css,/@media\(min-width:761px\) and \(max-width:820px\)[\s\S]*\.hero-original-art \{ left:50%; bottom:0; width:118vw; transform:translateX\(-50%\); \}/);assert.match(css,/@media\(max-width:760px\)[\s\S]*\.hero-original-art \{ left:50%; bottom:0; width:135vw; transform:translateX\(-50%\); \}/);assert.match(css,/@media \(min-width:821px\) and \(max-height:720px\)[\s\S]*\.hero-original-art \{ bottom:-6rem; width:min\(60vw,58rem\); \}/);assert.doesNotMatch(css,/\.hero-original-art img[^}]*object-fit:cover/);});

check("brand system contains no legacy accent identity",()=>{const css=readFileSync("app/globals.css","utf8"),designSystem=readFileSync("DESIGN_SYSTEM.md","utf8"),contrastTool=readFileSync("components/lab/contrast-tool.tsx","utf8"),visualSources=[css,designSystem,contrastTool].join("\n"),legacyHex="#d6"+"f342";assert.match(css,/--color-brand: #e45447/);assert.match(css,/--color-accent: var\(--color-brand\)/);assert.match(css,/--color-brand-soft: color-mix\(in srgb, var\(--color-brand\) 14%, transparent\)/);assert.match(css,/--color-brand-medium: color-mix\(in srgb, var\(--color-brand\) 32%, transparent\)/);assert.match(css,/--color-brand-strong: #b43d33/);assert.match(css,/--color-link-hover: var\(--color-brand-strong\)/);assert.equal(visualSources.toLowerCase().includes(legacyHex),false);assert.match(contrastTool,/useState\("#e45447"\)/);});

